<?php
require_once __DIR__.'/config/config.php';require_login();$uid=(int)current_user()['id'];$course_id=(int)($_GET['course_id']??0);
$s=db()->prepare("SELECT c.*,COUNT(DISTINCT l.id) total_lessons,COUNT(DISTINCT p.lesson_id) completed FROM courses c JOIN enrollments e ON e.course_id=c.id AND e.user_id=? LEFT JOIN lessons l ON l.course_id=c.id AND l.is_published=1 LEFT JOIN lesson_progress p ON p.lesson_id=l.id AND p.user_id=? WHERE c.id=? AND c.is_published=1 GROUP BY c.id");$s->execute([$uid,$uid,$course_id]);$course=$s->fetch();if(!$course){http_response_code(404);exit('Course not found or you are not enrolled.');}
if((int)$course['total_lessons']===0||(int)$course['completed']<(int)$course['total_lessons']){include __DIR__.'/includes/header.php';echo '<div class="empty">Complete every published lesson to unlock your certificate. Progress: '.(int)$course['completed'].' / '.(int)$course['total_lessons'].'</div>';include __DIR__.'/includes/footer.php';exit;}
$s=db()->prepare('SELECT * FROM certificates WHERE user_id=? AND course_id=?');$s->execute([$uid,$course_id]);$cert=$s->fetch();if(!$cert){$code='LF-'.strtoupper(bin2hex(random_bytes(8)));$s=db()->prepare('INSERT INTO certificates(user_id,course_id,certificate_code) VALUES(?,?,?)');$s->execute([$uid,$course_id,$code]);$cert=['id'=>(int)db()->lastInsertId(),'certificate_code'=>$code,'issued_at'=>date('Y-m-d H:i:s')];}
$verifyUrl=(getenv('LINGUAFREE_PUBLIC_URL')?:((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').BASE_URL)).'/verify.php?code='.rawurlencode($cert['certificate_code']);
$s=db()->prepare('SELECT * FROM certificate_credentials WHERE certificate_id=?');$s->execute([$cert['id']]);$credential=$s->fetch();$signature=certificate_signature($cert['certificate_code'],$uid,$course_id,$cert['issued_at']);if(!$credential){$s=db()->prepare('INSERT INTO certificate_credentials(certificate_id,credential_hash,verification_url) VALUES(?,?,?)');$s->execute([$cert['id'],$signature,$verifyUrl]);}else{$signature=$credential['credential_hash'];}
$page_title='Your certificate — LinguaFree';include __DIR__.'/includes/header.php';?>
<div class="certificate-actions"><span class="eyebrow">COURSE COMPLETED · VERIFIED RECORD</span><button class="btn btn-primary" onclick="window.print()">Print / Save as PDF ↓</button></div>
<section class="certificate"><div class="cert-mark">L</div><div class="cert-overline">LINGUAFREE · CERTIFICATE OF COMPLETION</div><h1>Certificate<br><em>of Achievement</em></h1><p class="cert-small">This certificate is proudly presented to</p><h2><?=e(current_user()['name'])?></h2><p class="cert-small">for successfully completing the language course</p><h3><?=e($course['title'])?></h3><p class="cert-description">The learner completed all <?= (int)$course['total_lessons']?> published lessons on LinguaFree.</p><div class="cert-bottom"><div><b><?=e(date('F j, Y',strtotime($cert['issued_at'])))?></b><small>DATE ISSUED</small></div><div class="cert-seal">✓<small>COMPLETED</small></div><div><b><?=e($cert['certificate_code'])?></b><small>VERIFICATION ID</small></div></div><div class="cert-qr"><img alt="QR code to verify certificate" src="https://api.qrserver.com/v1/create-qr-code/?size=120x120&data=<?=rawurlencode($verifyUrl)?>"><div><b>Public verification</b><p><?=e($verifyUrl)?></p><small>Credential fingerprint: <?=e(substr($signature,0,24))?>…</small></div></div></section>
<p class="small-note">This is a verifiable LinguaFree course-completion credential. It is not a government-issued, university-accredited or CEFR-certified qualification.</p>
<?php include __DIR__.'/includes/footer.php';?>
